  if(Event.current.type==EventType.KeyDown){if(Event.current.keyCode==KeyCode.Escape){Shortcut(false);Event.current.Use();}else if(Event.current.keyCode==KeyCode.I&&started){ToggleInventory();Event.current.Use();}else if(Event.current.keyCode==KeyCode.Tab&&started){Shortcut(true);Event.current.Use();}}
