 void Guide(){if(Sim.Expanded){ExpandedHelp();return;}Dim();Box(174,74,1092,752,ink);TabletTabs(2);Text(285,160,870,28,L("CADET FIELD GUIDE"),small,cyan);
  string guide=L("PICKUP AND BACKPACK GUIDE")+"\n\n"+L("01 / RESTORE AIR\nFind the torque driver in the sleeping pod beyond the shelter. Put it down near the air rack with Q. Turn air-cleaner power OFF. Pick up the spare CO2 cartridge and fit it at the rack's status screen. Pick up the driver and use the same screen to secure the cover. Restore air-cleaner power. A scrubber removes CO2; it does not make oxygen.\n\n02 / USE THE AIRLOCK\nEnter the airlock. Close the inner hatch and wait for it to seal. Use the wall display to vent (7 real seconds). Open the outer hatch only at vacuum. Close it behind you. On return, close the outer hatch, cycle to fill, then open the inner hatch. The suit is assumed equipped at the start.\n\n03 / BALANCE POWER\nTake the driver outside. Turn rover charging OFF to save 1.8 kW. Isolate MAIN POWER before repairing the array connection at the protected port. Restore main power promptly: air and thermal systems share this bus. An optional spare battery adds a finite 2 kWh; fit it to the battery bay only with the bus isolated. Local shadow lasts from hours 2 to 4.\n\n04 / PREPARE SHELTER\nCarry three water packs one at a time from the sleeping pod to the three lower north-shelf mounting clips in the storm shelter. Packs remain usable drinking water. During the separate particle drill at hours 5-7, spend at least 1.5 simulated hours inside the shelter itself. The sleeping pod does NOT count.\n\n05 / FINISH THE SHIFT\nComplete both repairs, stow all three packs, meet the shelter-time target and finish hour 8 with at least 1 kWh. Keep air cleaning and thermal control powered. Unsafe resources trigger a training review.\n\nSIMULATION NOTES\n1 real second = 40 simulated seconds. Lunar gravity is 1.62 m/s². Polar shadows depend on terrain; this two-hour outage is a fictional scenario, not a lunar night. Cabin volume is estimated at 70 m³ with two nominal crew. Reference consumption: 0.84 kg O2 and 1.00 kg CO2 per person per day. Oxygen storage and CO2 removal are separate. Power ratings, thermal response and repair rates are teaching assumptions. Radiation risk is dimensionless, not mSv or a medical prediction. The event is scripted, not a live NASA forecast. Exterior tones come from the suit interface.\n\nSHIFT LOG\n")+string.Join("\n\n",history);
  guide=L(guide).Replace("Put it down near the air rack with Q.","Store it in the backpack with R.").Replace("Pick up the driver and use the same screen", "Use the driver from your hand or backpack at the same socket");guide=MobileText(guide);float height=body.CalcHeight(new GUIContent(guide),820);scroll=TouchScrollView(new Rect(285,190,870,530),scroll,new Rect(0,0,825,height));GUI.Label(new Rect(0,0,820,height),guide,body);EndTouchScrollView();if(Button(285,745,415,42,L("BACK TO SHIFT"))){showLog=false;UpdateCursor();}if(Button(720,745,435,42,L("SCIENCE + SOURCES")))showSources=true;
 }
